// traza.cjs: graba una traza de Chromium con el protocolo de depuración (CDP) y cuenta eventos
const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const ctx = await b.newContext();
  const p = await ctx.newPage();
  const cdp = await ctx.newCDPSession(p);
  const eventos = [];
  cdp.on('Tracing.dataCollected', e => eventos.push(...e.value));
  await cdp.send('Tracing.start', { categories: 'devtools.timeline', transferMode: 'ReportEvents' });
  await p.goto('http://127.0.0.1:18610/?n=3000', { waitUntil: 'load' });
  await p.waitForTimeout(400);   // dejar que terminen el layout y la pintura
  const fin = new Promise(r => cdp.once('Tracing.tracingComplete', r));
  await cdp.send('Tracing.end'); await fin;
  const total = nombre => eventos.filter(e => e.name === nombre && e.ph === 'X')
                                 .reduce((s, e) => s + e.dur / 1000, 0);   // dur viene en microsegundos
  for (const n of ['ParseHTML', 'UpdateLayoutTree', 'Layout', 'Paint'])
    console.log(n, total(n).toFixed(1), 'ms');
  await b.close();
})();

const filas = [...document.querySelectorAll('.f')];   // 2000 divs

// Entrelazado: escribe y lee, escribe y lee...
for (const e of filas) {
  e.style.width = (e.offsetWidth + 1) + 'px';   // leer fuerza el layout, escribir lo invalida
}

// Agrupado: primero todas las lecturas, después todas las escrituras
const anchos = filas.map(e => e.offsetWidth);
filas.forEach((e, i) => { e.style.width = (anchos[i] + 1) + 'px'; });
